<script setup lang="ts">
import {ref,watch,onBeforeUnmount} from 'vue'
import type {ListeningData,PracticeQuestionInput} from '@/api/practice'
import {uploadPracticeAudio,adminAudioTicket} from '@/api/admin-practice'
import {errorMessage} from '@/api/identity'
const props=defineProps<{modelValue:ListeningData;questions:PracticeQuestionInput[];busy:boolean}>()
const emit=defineEmits<{'update:modelValue':[ListeningData];review:[];working:[boolean]}>()
const uploading=ref(false),error=ref(''),src=ref(''),name=ref(''),played=ref(false),audio=ref<HTMLAudioElement>()
let disposed=false,epoch=0
function set(value:Partial<ListeningData>){emit('update:modelValue',{...props.modelValue,...value,audioReviewed:false})}
async function preview(){const id=props.modelValue.audioAssetId;if(!id)return;const n=++epoch;error.value='';try{const ticket=await adminAudioTicket(id);if(disposed||n!==epoch)return;const url=new URL(ticket.url,location.origin);if(url.origin!==location.origin||!url.pathname.startsWith('/api/v1/practice/audio/'))throw new Error('音频地址无效');src.value=url.pathname+url.search;played.value=false}catch(e){if(!disposed)error.value=errorMessage(e)}}
async function upload(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file)return;if(file.size>80*1024*1024||!file.name.toLowerCase().endsWith('.mp3')){error.value='请选择不超过80MiB的MP3';return}uploading.value=true;emit('working',true);const n=++epoch;error.value='';try{const result=await uploadPracticeAudio(file);if(disposed||n!==epoch)return;name.value=result.originalName;set({audioAssetId:result.id});src.value='';played.value=false}catch(e){if(!disposed)error.value=errorMessage(e)}finally{if(!disposed){uploading.value=false;emit('working',false)}}}
function addGroup(){const all=props.questions.map(q=>q.key);const covered=new Set(props.modelValue.groups.flatMap(g=>g.questionKeys));const remaining=all.filter(k=>!covered.has(k));set({groups:[...props.modelValue.groups,{key:'g_'+crypto.randomUUID().replaceAll('-',''),title:'新分组',questionKeys:remaining}]})}
function range(index:number,edge:'start'|'end',value:string){const groups=JSON.parse(JSON.stringify(props.modelValue.groups)) as ListeningData['groups'],group=groups[index]!;let start=props.questions.findIndex(q=>q.key===(edge==='start'?value:group.questionKeys[0]));let end=props.questions.findIndex(q=>q.key===(edge==='end'?value:group.questionKeys.at(-1)));if(start<0)start=0;if(end<start)end=start;group.questionKeys=props.questions.slice(start,end+1).map(q=>q.key);set({groups})}
function title(index:number,value:string){const groups=JSON.parse(JSON.stringify(props.modelValue.groups)) as ListeningData['groups'];groups[index]!.title=value;set({groups})}
watch(()=>props.modelValue.audioAssetId,()=>{audio.value?.pause();src.value='';played.value=false})
onBeforeUnmount(()=>{disposed=true;epoch++;audio.value?.pause();emit('working',false)})
</script>
<template><section class="practice-panel" id="listening-editor"><h2>整套音频与分组</h2><p class="practice-hint">上传一份完整MP3；替换音频会撤销整套校对。题目和原文仍需保存、校对后发布。</p><label>上传完整音频<input id="listening.audioAssetId" type="file" accept=".mp3,audio/mpeg" :disabled="busy||uploading" @change="upload"></label><p v-if="uploading" role="status">正在上传音频…</p><p v-if="modelValue.audioAssetId" class="practice-hint">{{name||'已保存音频'}} · 资产 {{modelValue.audioAssetId}}</p><button :disabled="busy||uploading||!modelValue.audioAssetId" @click="preview">获取音频预听</button><audio v-if="src" ref="audio" :src="src" controls preload="metadata" @playing="played=true" @error="error='音频无法播放，请重新上传可播放的完整MP3';played=false"/><button id="listening.audioReviewed" :disabled="busy||uploading||!played||modelValue.audioReviewed" @click="audio?.pause();emit('review')">{{modelValue.audioReviewed?'已确认音频预听':'确认已预听并核对整套音频'}}</button><p v-if="error" class="practice-error" role="alert">{{error}}</p><div id="listening.groups"><h3>套内分组</h3><p class="practice-hint">每题只能属于一组，按题目顺序完整覆盖。调整题目后请核对范围。</p><div v-for="(group,index) in modelValue.groups" :key="group.key" class="listening-group"><label>分组名称<input :value="group.title" maxlength="120" :disabled="busy" @input="title(index,($event.target as HTMLInputElement).value)"></label><label>起始题<select :value="group.questionKeys[0]" :disabled="busy" @change="range(index,'start',($event.target as HTMLSelectElement).value)"><option v-for="(q,i) in questions" :key="q.key" :value="q.key">{{i+1}}</option></select></label><label>结束题<select :value="group.questionKeys.at(-1)" :disabled="busy" @change="range(index,'end',($event.target as HTMLSelectElement).value)"><option v-for="(q,i) in questions" :key="q.key" :value="q.key">{{i+1}}</option></select></label><button :disabled="busy" @click="set({groups:modelValue.groups.filter((_,i)=>i!==index)})">移除分组</button></div><button :disabled="busy||modelValue.groups.length>=20||!questions.length" @click="addGroup">添加套内分组</button></div></section></template>
<style scoped>audio{width:100%;display:block;margin:16px 0}.listening-group{display:grid;grid-template-columns:minmax(0,2fr) 1fr 1fr auto;gap:12px;align-items:center;margin:15px 0}@media(max-width:800px){.listening-group{grid-template-columns:1fr 1fr}.listening-group>label:first-child{grid-column:1/-1}}</style>
